"/**
 * SHA-256 Content Hashing Utility
 * Works in both browser (Web Crypto API) and Node.js environments.
 */
export async function calculateFileHash(file: File | Blob | ArrayBuffer | string): Promise<string> {
  let buffer: ArrayBuffer

  if (typeof file === 'string') {
    buffer = new TextEncoder().encode(file).buffer
  } else if (file instanceof ArrayBuffer) {
    buffer = file
  } else if (file instanceof Blob || (typeof File !== 'undefined' && file instanceof File)) {
    buffer = await file.arrayBuffer()
  } else {
    throw new Error('Desteklenmeyen dosya veya veri formatı.')
  }

  // Use Web Crypto API if available
  if (typeof crypto !== 'undefined' && crypto.subtle) {
    const hashBuffer = await crypto.subtle.digest('SHA-256', buffer)
    const hashArray = Array.from(new Uint8Array(hashBuffer))
    return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('')
  }

  // Fallback for Node.js test environment
  try {
    // Dynamic import to avoid bundling node:crypto in browser
    const nodeCrypto = await import('node:crypto')
    return nodeCrypto.createHash('sha256').update(Buffer.from(buffer)).digest('hex')
  } catch {
    throw new Error('Kriptografik hash fonksiyonu bu ortamda kullanılamıyor.')
  }
}
"

