const fs = require('fs');
const html = fs.readFileSync('/Users/evren/Downloads/Hesap_Hareketleri_07092026.html', 'utf8');

function extractFromHtml(htmlContent) {
  const rows = htmlContent.match(/<tr[^>]*>[\s\S]*?<\/tr>/gi) || [];
  const transactions = [];

  for (const row of rows) {
    const cells = (row.match(/<td[^>]*>([\s\S]*?)<\/td>/gi) || [])
      .map(c => c.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim());

    if (cells.length < 3) continue;

    // Check if first cell is a date: DD.MM.YYYY or DD/MM/YYYY
    const dateMatch = cells[0].match(/^(\d{1,2}[./-]\d{1,2}[./-](\d{2,4}))$/);
    if (!dateMatch) continue;

    // Format: [Tarih, Fiş No, Açıklama, Tutar, Bakiye]
    let desc = '';
    let amountStr = '';
    let balanceStr = '';

    if (cells.length >= 5) {
      desc = (cells[1] ? cells[1] + ' ' : '') + cells[2];
      amountStr = cells[3];
      balanceStr = cells[4];
    } else if (cells.length === 4) {
      desc = cells[1];
      amountStr = cells[2];
      balanceStr = cells[3];
    } else {
      desc = cells[1];
      amountStr = cells[2];
    }

    const cleanAmount = amountStr.replace(/[^\d.,-]/g, '').replace(/\.(?=\d{3})/g, '').replace(',', '.');
    const absAmount = Math.abs(parseFloat(cleanAmount));
    if (isNaN(absAmount) || absAmount === 0) continue;

    const isOutflow = cleanAmount.startsWith('-') || /Ödeme|Tahsilat|Para Çekme|Transfer/i.test(desc) && !/Gelen/i.test(desc);

    transactions.push({
      date: cells[0],
      desc,
      amount: absAmount,
      direction: cleanAmount.startsWith('-') ? 'outflow' : 'inflow'
    });
  }

  return transactions;
}

const txs = extractFromHtml(html);
console.log('Successfully extracted from HTML:', txs.length, 'transactions');
for (let i = 0; i < 5; i++) {
  console.log(txs[i]);
}
