function extractLast4(text) {
  const cardMaskMatch = text.match(/(?:[0-9]{4}[-\s*#xX]{4,16}(\d{4}))/i);
  if (cardMaskMatch) return cardMaskMatch[1];
  const labeledMatch = text.match(/(?:kart\s*no|kartı\s*no|kredi\s*kartı|kart\s*numaras[ıi])\s*[:.\-]?\s*[0-9*#xX\-\s]*?(\d{4})/i);
  if (labeledMatch) return labeledMatch[1];
  const starMatch = text.match(/[#*xX]{4,}\s*(\d{4})/i);
  if (starMatch) return starMatch[1];
  return undefined;
}

for (const f of files) {
  const data = new Uint8Array(fs.readFileSync(path.join(uploadedDir, f)));
  const doc = await getDocument({ data }).promise;
  let fullText = '';
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    const content = await page.getTextContent();
    fullText += content.items.map(it => it.str).join(' ') + '\n';
  }
  console.log(f, '=>', extractLast4(fullText));
}
