import * as fs from 'fs';
import * as XLSX from 'xlsx';

function fixWindows1254(str: string): string {
  if (!str) return '';
  return str
    .replace(/Þ/g, 'Ş')
    .replace(/þ/g, 'ş')
    .replace(/Ý/g, 'İ')
    .replace(/ý/g, 'ı')
    .replace(/Ð/g, 'Ğ')
    .replace(/ð/g, 'ğ');
}

const buf = fs.readFileSync('/Users/evren/Downloads/Hesap Hareketleri.csv');
const wb = XLSX.read(buf, { type: 'buffer' });
const ws = wb.Sheets[wb.SheetNames[0]];
const rows: Array<Array<any>> = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false });

let headerIdx = -1;
let colMap: Record<string, number> = {};

for (let r = 0; r < Math.min(rows.length, 20); r++) {
  const row = rows[r].map(c => fixWindows1254(String(c || '')).trim());
  const dIdx = row.findIndex(c => /tarih|date/i.test(c));
  const aIdx = row.findIndex(c => /tutar|amount/i.test(c));
  const descIdx = row.findIndex(c => /a[çc][ıi]klama|detay|i[şs]lem/i.test(c));
  if (dIdx !== -1 && (aIdx !== -1 || descIdx !== -1)) {
    headerIdx = r;
    colMap = {
      date: dIdx,
      amount: aIdx,
      balance: row.findIndex(c => /bakiye|balance/i.test(c)),
      desc: descIdx
    };
    break;
  }
}

console.log('Header found at row:', headerIdx, colMap);

let txCount = 0;
for (let r = headerIdx + 1; r < rows.length; r++) {
  const row = rows[r];
  if (!row || row.length === 0) continue;
  const rawDate = String(row[colMap.date] || '').trim();
  const dateMatch = rawDate.match(/^(\d{4})[./-](\d{1,2})[./-](\d{1,2})/) || rawDate.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})/);
  if (!dateMatch) continue;
  txCount++;
}
console.log('Valid transaction rows found:', txCount);
""

