const { createClient } = require('@supabase/supabase-js');
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://kvyslscyepxvkrcgsvvz.supabase.co';
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || 'sb_secret_vPvXHuM3z_PHFOTDPz_RxA_75tKKrUE';
const supabase = createClient(supabaseUrl, supabaseKey);
const userId = 'c74d8741-b8fb-4f79-83eb-f2fa9e12073f';

async function main() {
  // 1. Shift 25k from May to March
  console.log('--- 1. Updating May work (remove 25k) ---');
  await supabase.from('debts').update({
    past_payments: 0,
    remaining: 63300
  }).eq('id', '5f619ea7-b4a8-4111-874e-04628c87cbe7');

  console.log('--- 2. Updating March work (deduct 25k -> remaining 12700) ---');
  await supabase.from('debts').update({
    past_payments: 25000,
    remaining: 12700
  }).eq('id', 'd8c23790-139a-43d9-81ce-b8f1f894da8c');

  // 3. Ensure Akbank Artı Para exists
  const { data: existingAkbank } = await supabase.from('debts').select('*').eq('person_or_entity', 'Akbank');
  if (!existingAkbank || existingAkbank.length === 0) {
    console.log('--- 3. Inserting Akbank Artı Para row ---');
    await supabase.from('debts').insert({
      user_id: userId,
      type: 'Borç',
      category: 'Diğer',
      person_or_entity: 'Akbank',
      description: 'Artı Para',
      principal: 74.91,
      past_payments: 0,
      remaining: 74.91,
      status: 'Açık'
    });
  }

  // 4. Verify
  const { data: allDebts } = await supabase.from('debts').select('*').order('created_at');
  console.log('\n--- Final Debts State ---');
  allDebts.forEach((d, i) => {
    const newPayments = Math.max(0, d.principal - d.past_payments - d.remaining);
    console.log(
      (i+1) + ' | ' + d.type + ' | ' + d.category + ' | ' + d.person_or_entity + ' | ' + d.description + ' | Ana: ' + d.principal + ' | Geçmiş: ' + d.past_payments + ' | Yeni: ' + newPayments + ' | Kalan: ' + d.remaining
    );
  });
}
main();
